Get-ChildItem -Path 'C:\' -Directory -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -ne 'Windows' -and $_.Name -ne '$Recycle.Bin' } | ForEach-Object { $size = (Get-ChildItem -Path $_.FullName -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum -ErrorAction SilentlyContinue).Sum; [PSCustomObject]@{Path=$_.FullName; SizeGB=[math]::Round($size/1GB,2)} } | Sort-Object SizeGB -Descending | Format-Table -AutoSize
